    private val cachedWalkthroughs: Map<PatternType, List<WalkthroughExample>> by lazy {
        PatternType.entries.associateWith { type -> buildWalkthroughExamples(type) }
    }

    private val cachedExercises: Map<PatternType, List<Exercise>> by lazy {
        PatternType.entries.associateWith { type ->
            (1..10).map { idx -> createExerciseFromSeed(type, idx, isGenerated = false) }
        }
    }

    fun getWalkthroughExamples(patternType: PatternType): List<WalkthroughExample> =
        cachedWalkthroughs[patternType] ?: emptyList()

    fun getInitialExercises(patternType: PatternType): List<Exercise> =
        cachedExercises[patternType] ?: emptyList()

    /**
     * Dynamically creates a verified exercise (#11, #12, ...) by selecting across the 10 distinct
     * structural topologies for [patternType] and applying a fresh Sudoku group isomorphism.
     */
    fun generateExercise(patternType: PatternType, indexInPattern: Int): Exercise =
        createExerciseFromSeed(patternType, indexInPattern, isGenerated = true)

    private fun buildWalkthroughExamples(patternType: PatternType): List<WalkthroughExample> {
        val seeds = seedsByPattern.getValue(patternType)
        // Seeds 0 and 1 are the 2 distinct lesson walkthrough examples
        return listOf(0, 1).map { exampleIdx ->
            val rawBoard = parseSeedBoard(seeds[exampleIdx])
            val precomputed = CandidateCalculator.precomputeCandidates(rawBoard)
            val instance = PatternDetector.findFirstInstance(precomputed, patternType)
                ?: error("Failed to detect $patternType on walkthrough example #${exampleIdx + 1}")
            val title = if (exampleIdx == 0) "Example 1: Standard Formation" else "Example 2: Alternate Formation"
            WalkthroughExample(
                id = "${patternType.name}_EXAMPLE_${exampleIdx + 1}",
                patternType = patternType,
                title = title,
                board = precomputed,
                patternInstance = instance,
                step1SetupText = "Step 1 (The Setup): All row, column, and 3x3 block candidates are precomputed directly from the board. ${instance.stage1Hint}",
                step2LogicText = "Step 2 (Pattern Lock & Links): ${instance.stage2Hint}",
                step3EliminationText = "Step 3 (The Elimination): ${instance.stage3Hint}"
            )
        }
    }

    private fun createExerciseFromSeed(
        patternType: PatternType,
        indexInPattern: Int,
        isGenerated: Boolean
    ): Exercise {
        val seeds = seedsByPattern.getValue(patternType)
        // Seeds 2..11 are the 10 distinct exercise topologies
        val seedSlot = 2 + ((indexInPattern - 1).coerceAtLeast(0) % 10)
        val baseBoard = parseSeedBoard(seeds[seedSlot])
        val initialBoard = if (indexInPattern <= 10) {
            baseBoard
        } else {
            val isoSeed = patternType.complexityOrder * 53 + indexInPattern * 17
            val spec = SudokuIsomorphism.createSpec(isoSeed)
            SudokuIsomorphism.transformBoard(baseBoard, spec).copy(
                candidates = List(9) { List(9) { emptySet() } },
                candidatesPrecomputed = false
            )
        }
        val precomputed = CandidateCalculator.precomputeCandidates(initialBoard)
        val detectedInstance = PatternDetector.findFirstInstance(precomputed, patternType)
            ?: error("Failed to detect $patternType on exercise #$indexInPattern")

        return Exercise(
            id = "${patternType.name}_${indexInPattern.toString().padStart(2, '0')}",
            patternType = patternType,
            indexInPattern = indexInPattern,
            title = "${patternType.displayName} #${indexInPattern}",
            initialBoard = initialBoard,
            patternInstance = detectedInstance,
            isGenerated = isGenerated
        )
    }

    private fun parseSeedBoard(seed: VerifiedPuzzleSeed): SudokuBoard {
        val givens = List(9) { r ->
            List(9) { c -> seed.given81[r * 9 + c] - '0' }
        }
        val solution = List(9) { r ->
            List(9) { c -> seed.solution81[r * 9 + c] - '0' }
        }
        return SudokuBoard(
            givenDigits = givens,
            solutionDigits = solution,
            candidatesPrecomputed = false
        )
    }
}
